import json, os, pathlib, subprocess, tempfile

root = pathlib.Path(tempfile.mkdtemp(prefix='pr76-current-', dir='/private/tmp'))
bins = {'git': '/usr/bin/git', 'local': '/private/tmp/gogit-pr76-local-assessment'}
results = []

def fixture(name, binary, repo=True):
    d = root / name / binary
    d.mkdir(parents=True)
    home = d / 'home'
    home.mkdir()
    env = {k:v for k,v in os.environ.items() if not k.startswith('GIT_')}
    env.update(HOME=str(home), XDG_CONFIG_HOME=str(home/'xdg'), GIT_CONFIG_NOSYSTEM='1', LC_ALL='C', GIT_CEILING_DIRECTORIES=str(root))
    if repo:
        subprocess.run(['/usr/bin/git','init','-q','-b','main'], cwd=d, env=env, check=True)
    return d, env

def run(binary, d, env, args):
    p = subprocess.run([bins[binary]]+args, cwd=d, env=env, capture_output=True)
    return {'code':p.returncode, 'out':p.stdout.decode(errors='backslashreplace'), 'err':p.stderr.decode(errors='backslashreplace')}

def record(name, binary, result, **extra):
    results.append(dict(case=name, binary=binary, **result, **extra))

for b in bins:
    for name in ['symlink_parent', 'empty_file', 'git_config', 'empty_gitdir', 'explicit_empty_gitdir', 'bom', 'absent_branch', 'posix_class', 'relative_include', 'absolute_include', 'expand_path', 'explicit_system', 'terminal_cr', 'cleanup', 'include_symlink_parent']:
        d,e = fixture(name,b,repo=name not in ['empty_gitdir','explicit_empty_gitdir','absent_branch'])
        cfg=d/'.git/config'
        if name=='symlink_parent':
            (d/'real/sub').mkdir(parents=True); (d/'jump').symlink_to('real/sub')
            (d/'cfg').write_text('[x]\na=other\n'); (d/'real/cfg').write_text('[x]\na=intended\n')
            read=run(b,d,e,['config','--file','jump/../cfg','--get','x.a'])
            r=run(b,d,e,['config','--file','jump/../cfg','x.a','changed'])
            record(name,b,r,read=read,intended=(d/'real/cfg').read_text(),other=(d/'cfg').read_text())
        elif name=='empty_file':
            before=cfg.read_bytes()
            for args in [['config','--file=','x.a','changed'],['config','set','--file=','x.a','changed'],['config','--file=','--get','core.bare'],['config','get','--file=','core.bare']]:
                record(name,b,run(b,d,e,args),args=args,repo_unchanged=cfg.read_bytes()==before)
        elif name=='git_config':
            target=d/'selected'; target.write_text('[x]\na=selected\n'); e['GIT_CONFIG']=str(target)
            read=run(b,d,e,['config','--get','x.a']); before=cfg.read_bytes()
            r=run(b,d,e,['config','x.a','changed'])
            record(name,b,r,read=read,selected=target.read_text(),repo_unchanged=cfg.read_bytes()==before,repo=cfg.read_text())
        elif name in ['empty_gitdir','explicit_empty_gitdir']:
            (d/'.git').mkdir()
            if name=='explicit_empty_gitdir': e['GIT_DIR']=str(d/'.git')
            r=run(b,d,e,['config','x.a','changed'])
            record(name,b,r,created=cfg.exists(),contents=cfg.read_text() if cfg.exists() else None)
        elif name=='bom':
            target=d/'bom'; target.write_bytes(b'\xef\xbb\xbf[x]\na=yes\n')
            read=run(b,d,e,['config','--file',str(target),'--get','x.a'])
            r=run(b,d,e,['config','--file',str(target),'x.a','changed'])
            record(name,b,r,read=read,contents=target.read_text())
        elif name in ['absent_branch','posix_class']:
            inc=d/'included'; inc.write_text('[x]\na=included\n')
            pattern='*' if name=='absent_branch' else '[[:alpha:]]*'
            (pathlib.Path(e['HOME'])/'.gitconfig').write_text('[includeIf "onbranch:'+pattern+'"]\npath='+str(inc)+'\n')
            record(name,b,run(b,d,e,['config','--get','x.a']))
        elif name in ['relative_include','absolute_include']:
            target=d/'relative'; target.write_text('[x]\na=included\n')
            path='relative' if name=='relative_include' else str(target)
            record(name,b,run(b,d,e,['-c','include.path='+path,'config','--get','x.a']))
        elif name=='expand_path':
            target=d/'path'; target.write_text('[x]\na=~/link/../file\n')
            record(name,b,run(b,d,e,['config','--file',str(target),'--path','x.a']),home=e['HOME'])
        elif name=='explicit_system':
            target=d/'system'; target.write_text('[x]\na=system\n'); e['GIT_CONFIG_SYSTEM']=str(target)
            record(name,b,run(b,d,e,['config','--system','--get','x.a']))
        elif name=='terminal_cr':
            target=d/'cr'; target.write_bytes(b'[x]\n y = z\r')
            record(name,b,run(b,d,e,['config','--file',str(target),'--get','x.y']))
        elif name=='cleanup':
            target=d/'multi'; original=b'[x]\na=one\na=two\n'; target.write_bytes(original)
            failed=run(b,d,e,['config','--file',str(target),'x.a','changed'])
            intact=target.read_bytes()==original; no_lock=not (d/'multi.lock').exists()
            next_write=run(b,d,e,['config','--file',str(target),'x.b','next'])
            record(name,b,next_write,failed=failed,original_preserved=intact,no_lock_after_failure=no_lock,contents=target.read_text())
        elif name=='include_symlink_parent':
            (d/'real/sub').mkdir(parents=True); (d/'jump').symlink_to('real/sub')
            (d/'cfg').write_text('[x]\na=other\n'); (d/'real/cfg').write_text('[x]\na=intended\n')
            with cfg.open('a') as f: f.write('[include]\npath='+str(d)+'/jump/../cfg\n')
            record(name,b,run(b,d,e,['config','--get','x.a']))

(root/'results.json').write_text(json.dumps(results,indent=2))
print('Fixture root:',root)
for r in results: print(json.dumps(r))

